def para(text,style='p',gap=6):
 global y
 p=Paragraph(text,styles[style]);_,h=p.wrap(cw,1000);p.drawOn(c,M,y-h);y-=h+gap
 if y<35:raise RuntimeError('Page overflow '+str(page))
